// First-party project state. Native owns parsing, typing and all computation.
import 'dart:convert';
import 'dart:math';
import 'store.dart';

typedef FqeAuthoringRpc = Future<Map<String, dynamic>> Function(
    String method, Map<String, dynamic> params);
const _sourceLimit = 65536;
const _counterLimit = 9007199254740991;
const _emptyBindings = '{"version":1,"values":{}}';
Map<String, dynamic> _copy(Map<String, dynamic> v) => fqeJson(jsonEncode(v));
int _next(int n) {
  if (n >= _counterLimit) throw StateError('项目修订计数已达上限');
  return n + 1;
}

void _source(String text) {
  if (utf8.encode(text).length > _sourceLimit) {
    throw StateError('策略文本超过 64 KiB');
  }
}

void _validName(String name) {
  if (name.trim().isEmpty || name.length > 120) {
    throw StateError('策略名称须为 1–120 字符');
  }
}

/// A project has one native semantic document, two views and a retained buffer.
/// Every await is followed by a revision/generation check before publication.
class FqeAuthoringProject {
  FqeAuthoringProject._(this.id, this._name, this._buffer, this._rpc);
  final String id;
  String _name, _buffer;
  String _appliedSource = '', _parameters = _emptyBindings;
  String _appliedParameters = _emptyBindings;
  final FqeAuthoringRpc _rpc;
  int _revision = 0, _generation = 0;
  bool _pending = true;
  Map<String, dynamic>? _inspected;
  Map<String, dynamic> _research = {}, _presentation = {};
  List<dynamic> _diagnostics = [];
  String get name => _name;
  String get buffer => _buffer;
  String get parameters => _parameters;
  int get revision => _revision;
  int get generation => _generation;
  bool get pending => _pending;
  bool get executable => !_pending && _inspected != null;
  Map<String, dynamic>? get inspection =>
      _inspected == null ? null : _copy(_inspected!);
  Map<String, dynamic> get research => _copy(_research);
  Map<String, dynamic> get presentation => _copy(_presentation);
  List<dynamic> get diagnostics => jsonDecode(jsonEncode(_diagnostics)) as List;

  static Future<FqeAuthoringProject> create(
      {required String name,
      required String source,
      required FqeAuthoringRpc rpc}) async {
    _validName(name);
    _source(source);
    final random = Random.secure();
    final id =
        'p${List.generate(16, (_) => random.nextInt(256).toRadixString(16).padLeft(2, '0')).join()}';
    final p = FqeAuthoringProject._(id, name, source, rpc);
    if (!await p.apply(0, 0)) throw StateError('初始策略未通过原生校验');
    return p;
  }

  void _check(int revision, int generation) {
    if (revision != _revision || generation != _generation) {
      throw StateError('策略已变化，请重新校验当前修订');
    }
  }

  void rename(String name) {
    _validName(name);
    if (_name == name) return;
    _generation = _next(_generation);
    _name =
        name; // ID and executable semantic identity are independent of name.
  }

  void editText(String source) {
    _source(source);
    if (_buffer == source) return;
    _generation = _next(_generation);
    _buffer = source;
    _pending = true;
    _diagnostics = [];
  }

  void setParameters(Map<String, dynamic> parameters) {
    final copy = _copy(parameters);
    if (copy.length != 2 || copy['version'] != 1 || copy['values'] is! Map) {
      throw StateError('需要版本化的精确参数绑定');
    }
    final text = jsonEncode(copy);
    if (text == _parameters) return;
    _generation = _next(_generation);
    _parameters = text;
    _pending = true;
  }

  void setResearch(Map<String, dynamic> settings) {
    const keys = [
      'history_spec',
      'csv',
      'start_ns',
      'end_ns',
      'warmup_bars',
      'run',
      'seed',
      'account'
    ];
    if (settings.keys.any((k) => !keys.contains(k))) {
      throw StateError('运行配置不能另存策略模型、策略规则或参数');
    }
    final copy = _copy(settings);
    if (fqeInputId(copy) == fqeInputId(_research)) return;
    _generation = _next(_generation);
    _research = copy;
  }

  void setPresentation(Map<String, dynamic> value) {
    _presentation = _copy(value); // Layout never changes executable identity.
  }

  Future<bool> apply(int revision, int generation) async {
    _check(revision, generation);
    final source = _buffer, parameters = _parameters;
    final result = await _rpc(
        'authoring.inspect', {'source': source, 'parameters': parameters});
    _check(revision, generation);
    if (result['valid'] != true) {
      _diagnostics = result['diagnostics'] as List? ?? [];
      _pending = true;
      return false;
    }
    _install(result, source, parameters);
    return true;
  }

  void _install(Map<String, dynamic> result, String source, String parameters) {
    final frozen = _copy(result);
    if (frozen['document'] is! Map ||
        frozen['native'] is! Map ||
        frozen['comments'] is! List ||
        frozen['source_map'] is! List ||
        frozen['native']['execution_id'] is! String) {
      throw StateError('原生作者前端返回无效结构');
    }
    final changed = _inspected != null &&
        (_semanticId(frozen) != _semanticId(_inspected!) ||
            frozen['native']['execution_id'] !=
                _inspected!['native']['execution_id']);
    final next = changed ? _next(_revision) : _revision;
    _inspected = frozen;
    _revision = next;
    _buffer = _appliedSource = source;
    _parameters = _appliedParameters = parameters;
    _diagnostics = [];
    _pending = false;
  }

  static String _semanticId(Map<String, dynamic> v) => fqeInputId({
        // Native execution identity canonicalizes the graph and exact bindings.
        'execution_id': v['native']['execution_id'],
        'policies': v['document']['policies']
      });

  Future<void> editGraph(
      int revision, int generation, Map<String, dynamic> document) async {
    _check(revision, generation);
    if (!executable) throw StateError('请先应用或明确放弃当前文本修改');
    final frozen = _copy(document), parameters = _parameters;
    final printed = await _rpc('authoring.print',
        {'document': frozen, 'comments': _inspected!['comments']});
    _check(revision, generation);
    if (printed['valid'] != true || printed['source'] is! String) {
      throw StateError('此模型无法无损转换为当前作者语法');
    }
    final source = printed['source'] as String;
    final inspected = await _rpc(
        'authoring.inspect', {'source': source, 'parameters': parameters});
    _check(revision, generation);
    if (inspected['valid'] != true) throw StateError('图模型未通过原生校验');
    final next = _next(_generation);
    _install(inspected, source, parameters);
    _generation = next;
  }

  void discardBuffer(int revision, int generation) {
    _check(revision, generation);
    if (_inspected == null) throw StateError('没有可恢复的有效策略');
    _generation = _next(_generation);
    _buffer = _appliedSource;
    _parameters = _appliedParameters;
    _pending = false;
    _diagnostics = [];
  }

  /// Frozen input plus an outer association. Association never enters native IR.
  FqeProjectRun freeze() {
    if (!executable) throw StateError('当前策略文本尚未应用或校验失败，禁止运行旧模型');
    const keys = [
      'history_spec',
      'csv',
      'start_ns',
      'end_ns',
      'warmup_bars',
      'run',
      'seed',
      'account'
    ];
    if (keys.any((k) => !_research.containsKey(k))) {
      throw StateError('请先选择完整行情、时间范围和账户成本');
    }
    final input = _copy({
      ..._research,
      'kind': 'event',
      'model': jsonEncode(_inspected!['document']['model']),
      'policies': _inspected!['document']['policies'],
      'parameters': _parameters
    });
    return FqeProjectRun._(id, _revision, _generation, input, {
      'format': 'finger-desk.fqe-project-run/1',
      'project_id': id,
      'project_name': _name,
      'revision': '$_revision',
      'generation': '$_generation',
      'semantic_id': _semanticId(_inspected!),
      'execution_id': _inspected!['native']['execution_id'],
      'registry_id': _inspected!['native']['registry_id'],
      'input_id': fqeInputId(input)
    });
  }

  void requireCurrent(FqeProjectRun run) {
    if (!executable ||
        run.projectId != id ||
        run.revision != _revision ||
        run.generation != _generation ||
        freeze().inputId != run.inputId) {
      throw StateError('确认后策略或运行配置已变化，请重新预检');
    }
  }

  Map<String, dynamic> snapshot() => _copy({
        'format': 'finger-desk.fqe-authoring-project/1',
        'id': id,
        'name': _name,
        'revision': '$_revision',
        'generation': '$_generation',
        'applied_source': _appliedSource,
        'buffer': _buffer,
        'pending': _pending,
        'applied_parameters': _appliedParameters,
        'parameters': _parameters,
        'research': _research,
        'presentation': _presentation,
        'semantic_id': _inspected == null ? null : _semanticId(_inspected!)
      });
  static Future<FqeAuthoringProject> restore(
      Map<String, dynamic> snapshot, FqeAuthoringRpc rpc) async {
    final s = _copy(snapshot);
    if (s.length != 13 ||
        s['format'] != 'finger-desk.fqe-authoring-project/1' ||
        s['id'] is! String ||
        !RegExp(r'^p[0-9a-f]{32}$').hasMatch(s['id']) ||
        s['name'] is! String ||
        s['applied_source'] is! String ||
        s['buffer'] is! String ||
        s['pending'] is! bool ||
        s['parameters'] is! String ||
        s['applied_parameters'] is! String ||
        s['research'] is! Map<String, dynamic> ||
        s['presentation'] is! Map<String, dynamic>) {
      throw StateError('项目草稿结构或版本无效，原件已保留');
    }
    int count(String key) {
      final text = s[key];
      final n = text is String ? int.tryParse(text) : null;
      if (n == null || n < 0 || n > _counterLimit || '$n' != text) {
        throw StateError('项目修订计数无效');
      }
      return n;
    }

    _validName(s['name']);
    _source(s['buffer']);
    _source(s['applied_source']);
    final p =
        FqeAuthoringProject._(s['id'], s['name'], s['applied_source'], rpc);
    p._parameters = s['applied_parameters'];
    if (!await p.apply(0, 0) ||
        _semanticId(p._inspected!) != s['semantic_id']) {
      throw StateError('已保存策略与当前原生语义不一致，请显式迁移');
    }
    if (s['pending'] == false &&
        (s['buffer'] != s['applied_source'] ||
            s['parameters'] != s['applied_parameters'])) {
      throw StateError('草稿状态不一致');
    }
    p._buffer = s['buffer'];
    p._parameters = s['parameters'];
    // Decode bindings even for an invalid pending source; never evaluate it.
    final bindings = fqeJson(p._parameters);
    if (bindings.length != 2 ||
        bindings['version'] != 1 ||
        bindings['values'] is! Map) throw StateError('参数草稿无效');
    p._pending = s['pending'];
    p._revision = count('revision');
    p._generation = count('generation');
    p.setResearch(s[
        'research']); // Validates allowed keys; restore original generation below.
    p._generation = count('generation');
    p._presentation = s['presentation'];
    return p;
  }
}

/// Copies on every read prevent a caller mutating accepted input after preflight.
class FqeProjectRun {
  FqeProjectRun._(this.projectId, this.revision, this.generation,
      Map<String, dynamic> input, Map<String, dynamic> association)
      : _input = _copy(input),
        _association = _copy(association);
  final String projectId;
  final int revision, generation;
  final Map<String, dynamic> _input, _association;
  String get inputId => _association['input_id'] as String;
  Map<String, dynamic> get input => _copy(_input);
  Map<String, dynamic> get association => _copy(_association);
}

// Read-only projection of a hash-verified native financial report. No ledger.
import 'dart:convert';
import 'store.dart';

Map<String, dynamic> _copy(Map<String, dynamic> v) => fqeJson(jsonEncode(v));
List<Map<String, dynamic>> _rows(dynamic value) {
  if (value is! List) throw StateError('原生回放记录缺少列表');
  return value.cast<Map<String, dynamic>>();
}

class FqeReplayFrame {
  FqeReplayFrame._(
      this.sourceSequence,
      this.timestampNs,
      this.phase,
      Map<String, dynamic> account,
      Map<String, dynamic>? equity,
      List<Map<String, dynamic>> receipts)
      : _account = _copy(account),
        _equity = equity == null ? null : _copy(equity),
        _receipts = List.unmodifiable(receipts);
  final String sourceSequence, timestampNs, phase;
  final Map<String, dynamic> _account;
  final Map<String, dynamic>? _equity;
  final List<Map<String, dynamic>> _receipts;
  Map<String, dynamic> get account => _copy(_account);

  /// Native equity is close-sampled only. Open-phase valuation is unavailable.
  Map<String, dynamic>? get equity => _equity == null ? null : _copy(_equity);
  List<Map<String, dynamic>> get receipts => _receipts.map(_copy).toList();
}

/// The versioned backtest profile records one Bar receipt followed by one Submit
/// per submitted decision, then Finish. We validate that schedule before reading
/// receipt accounts; we never reconstruct balances from fills or candle prices.
class FqeNativeReplay {
  FqeNativeReplay._(this.resultId, this.terminal, this._report, this._frames);
  final String resultId, terminal;
  final Map<String, dynamic> _report;
  final List<FqeReplayFrame> _frames;
  bool get partial => terminal != 'completed';
  int get frameCount => _frames.length;
  Map<String, dynamic> get metrics => _copy(_report['metrics']);
  Map<String, dynamic> get finalAccount => _copy(_report['account']);
  FqeReplayFrame at(int index) {
    if (index < 0 || index >= _frames.length) {
      throw RangeError.index(index, _frames);
    }
    return _frames[index];
  }

  FqeReplayFrame seek(String sourceSequence, String phase) =>
      _frames.firstWhere(
          (f) => f.sourceSequence == sourceSequence && f.phase == phase,
          orElse: () => throw StateError('此来源序号或阶段没有已核验回放帧'));

  factory FqeNativeReplay.fromRecord(Map<String, dynamic> record) {
    final raw = record['report'], result = record['result_id'];
    if (raw is! String ||
        result is! String ||
        fqeResultId(utf8.encode(raw)) != result) {
      throw StateError('回放结果缺失或哈希不匹配，不会重新运行策略');
    }
    final report = fqeJson(raw);
    if (report['format'] != 'fqe.backtest-result' ||
        report['schema_version'] != 1 ||
        report['manifest']['engine_id'] != record['engine_id'] ||
        !['completed', 'cancelled', 'stopped'].contains(report['terminal']) ||
        report['manifest']['financial_execution']['margin'] != null ||
        report['manifest']['financial_execution']['model'] !=
            'fqe.next-open-prior-volume/1' ||
        report['manifest']['account']['profile'] !=
            'fqe.gross-basis-cash-long/1' ||
        report['manifest']['phases'] !=
            'incoming-open-fill;closed-strategy;ordered-policy;close-equity') {
      throw StateError('回放版本、来源或终止状态不受支持');
    }
    final observations = _rows(report['observations']),
        decisions = _rows(report['decisions']);
    final receipts = _rows(report['execution_events']),
        curve = _rows(report['equity_curve']);
    final journal = _rows(report['journal']);
    if (journal.isEmpty || journal.first['opening'] == null) {
      throw StateError('缺少原生期初账户');
    }
    final duration = BigInt.parse(
        report['manifest']['history_inputs']['history']['duration_ns']);
    if (duration <= BigInt.zero) throw StateError('来源周期无效');
    var cursor = 0;
    final frames = <FqeReplayFrame>[
      FqeReplayFrame._('0', '0', 'initial', journal.first['after'], null, [])
    ];
    Map<String, dynamic> consume() {
      if (cursor >= receipts.length ||
          receipts[cursor]['command_sequence'] != '${cursor + 1}') {
        throw StateError('原生执行回执序号不连续');
      }
      return receipts[cursor++];
    }

    var previous = BigInt.zero;
    for (final observation in observations) {
      final sequence = observation['source_sequence'] as String;
      final number = BigInt.parse(sequence),
          close = BigInt.parse(observation['timestamp_ns']);
      if (number <= previous || close < duration) throw StateError('来源顺序或时间无效');
      previous = number;
      final bar = consume();
      // Cash Bar receipts precede policy submissions. Native fills are retained;
      // margin profiles require their own explicitly verified phase adapter.
      if (_rows(bar['events']).any((e) => e['kind'] == 'finished')) {
        throw StateError('提前结束回执');
      }
      frames.add(FqeReplayFrame._(sequence, '${close - duration}', 'open',
          bar['account'], null, receipts.take(cursor).toList()));
      final submissions = decisions
          .where((d) =>
              d['source_sequence'] == sequence && d['outcome'] == 'submitted')
          .toList();
      for (final decision in submissions) {
        final submit = consume();
        if (!_rows(submit['events']).any((e) =>
            e['kind'] == 'order' &&
            e['order']['intent']['id'] == decision['order'])) {
          throw StateError('策略提交与原生回执不匹配');
        }
      }
      final points =
          curve.where((p) => p['source_sequence'] == sequence).toList();
      if (points.length > 1) throw StateError('重复收盘权益');
      frames.add(FqeReplayFrame._(
          sequence,
          '$close',
          'close',
          receipts[cursor - 1]['account'],
          points.isEmpty ? null : points.single,
          receipts.take(cursor).toList()));
    }
    final finish = consume();
    if (cursor != receipts.length ||
        !_rows(finish['events']).any((e) => e['kind'] == 'finished') ||
        fqeInputId(finish['account']) != fqeInputId(report['account'])) {
      throw StateError('终止回执与最终账户不匹配');
    }
    frames.add(FqeReplayFrame._(
        observations.isEmpty ? '0' : observations.last['source_sequence'],
        observations.isEmpty ? '0' : observations.last['timestamp_ns'],
        'terminal',
        finish['account'],
        null,
        receipts));
    return FqeNativeReplay._(result, report['terminal'], report, frames);
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:isolate';
import 'dart:math';
import 'client.dart';
import 'authoring.dart';
import 'managed_client.dart';
import 'store.dart';

/// Independent of widgets, login, Python and the legacy Dart ledger. Persistent
/// writes and full-result verification run off the UI isolate. No auto retries.
class FqeApplicationService {
  FqeApplicationService(this.store, this.executable, this.bundle);
  final FqeStore store;
  final String executable;
  final Map<String, dynamic> bundle;
  ManagedClient? _client;
  StreamSubscription<RunView>? _subscription;
  final _changes = StreamController<void>.broadcast();
  final _active = <String, Map<String, dynamic>>{};
  Future<void>? _watching;
  Future<void>? _opening;
  bool _closing = false;
  Set<String> _capabilities = {};
  int _selection = 0;
  final authoringProjects = <String, FqeAuthoringProject>{};
  String? failure;
  Map<String, dynamic>? editorState;
  Map<String, dynamic>? lastInspection, report;
  List<Map<String, dynamic>> drafts = [], history = [];
  Map<String, dynamic>? current;
  RunView? view;
  Stream<void> get changes => _changes.stream;
  bool get busy => _opening != null || _active.isNotEmpty;
  bool get ready => _client != null && !_closing;
  int? get nativeProcessId => _client?.pipe.process.pid;
  String get engineId => '${bundle['financial_engine_id']}';
  void _notify() {
    if (!_changes.isClosed) _changes.add(null);
  }

  Future<void> initialize() async {
    await store.initialize();
    await reload(); // Historical reading remains available without the engine.
  }

  Future<void> reload() async {
    drafts = await store.list('draft');
    history = await store.list('run');
    _notify();
  }

  Future<void> connect() => _opening ??= _connect().whenComplete(() {
        _opening = null;
        _notify();
      });
  Future<void> _connect() async {
    if (_closing) throw StateError('引擎服务正在退出');
    if (_client != null) return;
    if (bundle['format'] != 'finger-desk.fqe-bundle/1' ||
        bundle['platform'] != 'macos-arm64' ||
        bundle['max_request_bytes'] != maxRequest ||
        bundle['max_response_bytes'] != maxResponse) {
      throw StateError('内置引擎清单版本不支持或未随应用打包');
    }
    // The only production path is the verified helper delivered with this app.
    final path = executable, expected = bundle['executable_sha256'];
    await _verifyExecutable(path, expected);
    final client = await ManagedClient.start(executable);
    try {
      final hello = await client.pipe.hello();
      if (hello['bridge_id'] != bundle['bridge_id']) {
        throw StateError('内置引擎协议身份不匹配');
      }
      if (_closing) throw StateError('引擎服务正在退出');
      _capabilities = (hello['capabilities'] as List).cast<String>().toSet();
      _client = client;
      _subscription = client.updates.listen((value) {
        view = value;
        _notify();
      });
      failure = null;
    } catch (_) {
      await client.close();
      rethrow;
    }
  }

  Future<Map<String, dynamic>> inspect(Map<String, dynamic> input) async {
    await connect();
    final result = await _client!.pipe.call('model.inspect', {
      for (final key in ['kind', 'model', 'parameters']) key: input[key]
    });
    lastInspection = result;
    _notify();
    return result;
  }

  /// Optional authoring extension: old bundles fail explicitly, never fall back.
  Future<Map<String, dynamic>> authoringRpc(
      String method, Map<String, dynamic> params) async {
    final capability = method == 'catalog.describe'
        ? 'catalog.describe/1'
        : 'authoring.event/1';
    if (!['catalog.describe', 'authoring.inspect', 'authoring.print']
        .contains(method)) {
      throw StateError('不支持的作者前端方法');
    }
    final frozen = fqeJson(jsonEncode(params), max: maxRequest);
    await connect();
    if (!_capabilities.contains(capability)) {
      throw StateError('当前内置引擎不支持统一作者前端，请更新完整应用');
    }
    return _client!.pipe.call(method, frozen);
  }

  Future<FqeAuthoringProject> createAuthoringProject(
      String name, String source) async {
    final project = await FqeAuthoringProject.create(
        name: name, source: source, rpc: authoringRpc);
    await saveAuthoringProject(project);
    authoringProjects[project.id] = project;
    return project;
  }

  Future<List<Map<String, dynamic>>> listAuthoringProjects() =>
      store.list('project');

  Future<String> saveAuthoringProject(FqeAuthoringProject project) async {
    final snapshot = project.snapshot();
    final id = 'p${fqeInputId(snapshot)}';
    await store.put('project', id, snapshot);
    return id;
  }

  Future<FqeAuthoringProject> openAuthoringProject(String snapshotId) async {
    final snapshot = await store.read('project', snapshotId);
    final id = snapshot['id'];
    if (authoringProjects.containsKey(id)) {
      throw StateError('此项目已打开，请显式解决当前草稿后再恢复快照');
    }
    final project = await FqeAuthoringProject.restore(snapshot, authoringRpc);
    if (authoringProjects.containsKey(id)) {
      throw StateError('恢复期间项目已打开，旧快照未覆盖当前草稿');
    }
    authoringProjects[project.id] = project;
    return project;
  }

  Future<void> startProject(
          FqeAuthoringProject project, FqeProjectRun frozen) =>
      startAssociated(frozen.input,
          name: project.name,
          project: frozen.association,
          requireCurrent: () => project.requireCurrent(frozen));

  Future<Map<String, dynamic>> preflight(Map<String, dynamic> input) async {
    await connect();
    return _client!.pipe.call('backtest.validate', input);
  }

  Future<String> saveDraft(String name, Map<String, dynamic> input) async {
    final frozen = fqeJson(jsonEncode(input), max: maxRequest);
    if (name.trim().isEmpty || name.length > 128) {
      throw StateError('策略名称须为 1–128 个字符');
    }
    final inspected = await inspect(frozen);
    final id = fqeInputId({'name': name, 'input': frozen});
    if (drafts.any((d) => d['id'] == id && d['error'] == null)) return id;
    await store.put('draft', id, {
      'name': name,
      'created': DateTime.now().toUtc().toIso8601String(),
      'input': frozen,
      'input_id': fqeInputId(frozen),
      'execution_id': inspected['execution_id'],
      'registry_id': inspected['registry_id'],
      'bridge_id': bundle['bridge_id']
    });
    await reload();
    return id;
  }

  Future<Map<String, dynamic>> loadDraft(String id) async {
    final value = await store.read('draft', id);
    if (value['input_id'] !=
        fqeInputId(value['input'] as Map<String, dynamic>)) {
      throw StateError('策略身份不匹配');
    }
    return value;
  }

  Future<void> start(Map<String, dynamic> input, {String name = '本地回测'}) =>
      startAssociated(input, name: name);

  Future<void> startAssociated(Map<String, dynamic> input,
      {String name = '本地回测',
      Map<String, dynamic>? project,
      void Function()? requireCurrent}) async {
    if (busy || _closing) throw StateError('已有任务或服务正在关闭');
    // Freeze synchronously before initialization/validation/file IO can yield.
    requireCurrent?.call();
    final frozen = fqeJson(jsonEncode(input), max: maxRequest);
    final association = project == null ? null : fqeJson(jsonEncode(project));
    if (association != null &&
        (association['format'] != 'finger-desk.fqe-project-run/1' ||
            association['input_id'] != fqeInputId(frozen))) {
      throw StateError('项目运行关联与冻结输入不一致');
    }
    final selection = ++_selection;
    report = null;
    current = null;
    failure = null;
    view = null;
    final id =
        'r${DateTime.now().microsecondsSinceEpoch}_${Random.secure().nextInt(1 << 32)}';
    final record = <String, dynamic>{
      'name': name,
      'created': DateTime.now().toUtc().toIso8601String(),
      'input': frozen,
      'input_id': fqeInputId(frozen),
      'backend': 'fqe-native/1',
      'bridge_id': bundle['bridge_id'],
      'engine_id': engineId,
      'phase': 'preparing',
      if (association != null) 'project': association
    };
    _active[id] = record;
    current = record;
    _notify();
    try {
      await preflight(frozen);
      requireCurrent?.call();
      if (record['stop_requested'] == true || _closing) {
        throw StateError('准备阶段已取消');
      }
      // Persist accepted input before executing. An unpaired interrupted input
      // remains readable and is never silently re-executed on the next launch.
      await store.put('run', '$id.input', record);
      requireCurrent?.call();
      if (record['stop_requested'] == true || _closing) {
        throw StateError('准备阶段已取消');
      }
      final run = await _client!.startRun(id, frozen);
      record['handle'] = run.handle;
      view = run;
      _notify();
      final task = _finish(id, record, run.handle, selection);
      _watching = task;
      unawaited(task.whenComplete(() {
        _watching = null;
      }));
    } catch (e) {
      _active.remove(id);
      record['phase'] =
          record['stop_requested'] == true ? 'cancelled' : 'failed';
      failure = '$e';
      _notify();
      rethrow;
    }
  }

  Future<void> _finish(String id, Map<String, dynamic> record, String handle,
      int selection) async {
    final client = _client!;
    try {
      RunView status;
      do {
        status = await client.refresh(handle);
        if (!status.terminal) {
          await Future<void>.delayed(const Duration(milliseconds: 100));
        }
      } while (!status.terminal);
      final finalRecord = <String, dynamic>{
        ...record,
        'phase': status.phase,
        'result_id': status.resultId,
        'error': status.errorCode
      };
      Map<String, dynamic>? verified;
      if (status.resultId != null) {
        final bytes = await client.resultBytes(handle);
        final expected = status.resultId!, expectedEngine = engineId;
        verified = await _verifyResult(bytes, expected, expectedEngine);
        finalRecord['report'] = utf8.decode(bytes);
      }
      await store.put('run', id, finalRecord);
      if (selection == _selection) {
        current = finalRecord;
        report = verified;
      }
      if (status.phase == 'failed' || status.phase == 'interrupted') {
        failure = '运行${status.phase}：${status.errorCode}';
      }
      await client.release(handle);
      await reload();
    } catch (e) {
      report = null;
      failure = '运行或结果保存失败：$e';
      // Retain the native terminal until service shutdown if saving failed.
      // The immutable .input record remains, with no persisted success claim.
    } finally {
      _active.remove(id);
      _notify();
    }
  }

  Future<void> stop() async {
    for (final record in _active.values.toList()) {
      record['stop_requested'] = true;
      final handle = record['handle'];
      if (handle is String && _client?.runs[handle]?.terminal == false) {
        try {
          await _client?.stop(handle);
        } catch (_) {
          if (_client?.runs[handle]?.terminal != true) rethrow;
        }
      }
    }
  }

  Future<void> openResult(String id) async {
    if (busy) throw StateError('请等待当前任务结束');
    final selection = ++_selection;
    report = null;
    current = null;
    failure = null;
    _notify();
    try {
      final value = await store.read('run', id);
      final text = value['report'], expected = value['result_id'];
      Map<String, dynamic>? parsed;
      if (text is String) {
        parsed = await _verifyResult(
            utf8.encode(text), expected, value['engine_id']);
      }
      if (selection != _selection) return;
      current = value;
      report = parsed;
      if (parsed == null) failure = '此记录没有已保存的财务结果；不会自动重新执行';
    } catch (e) {
      if (selection == _selection) failure = '记录读取失败：$e';
      rethrow;
    } finally {
      _notify();
    }
  }

  Future<void> shutdown() async {
    _closing = true;
    try {
      await _opening;
    } catch (_) {/* Startup failure still releases storage. */}
    try {
      await stop();
    } catch (_) {/* Dead peer is joined by close below. */}
    try {
      await _client?.close();
      await _watching;
    } finally {
      await _subscription?.cancel();
      await store.close();
      unawaited(_changes.close());
    }
  }
}

Future<void> _verifyExecutable(String path, dynamic expected) =>
    Isolate.run(() async {
      final file = File(path);
      if (!file.isAbsolute ||
          await FileSystemEntity.type(path, followLinks: false) !=
              FileSystemEntityType.file ||
          await file.length() > 32 * 1024 * 1024 ||
          fqeHash(await file.readAsBytes()) != expected) {
        throw StateError('内置引擎缺失或校验失败，请更新完整应用');
      }
    });
Future<Map<String, dynamic>> _verifyResult(
        List<int> bytes, String expected, String engine) =>
    Isolate.run(() {
      if (fqeResultId(bytes) != expected) throw StateError('原生结果校验失败');
      final v = fqeJson(utf8.decode(bytes));
      if (v['format'] != 'fqe.backtest-result' ||
          v['schema_version'] != 1 ||
          v['manifest']['engine_id'] != engine) {
        throw StateError('结果版本或引擎身份不匹配');
      }
      return v;
    });

import 'dart:convert';
import 'dart:io';
import 'dart:isolate';
import '../contracts/strict_json.dart';
import '../persistence/quant_encoding.dart';

const fqeStoreLimit = 256 * 1024 * 1024;
const fqeRecordLimit = 10 * 1024 * 1024;

Map<String, dynamic> fqeJson(String text, {int max = fqeRecordLimit}) {
  if (utf8.encode(text).length > max) throw StateError('记录超出大小限制');
  // Bound nesting before the existing strict duplicate-key parser recurses.
  var depth = 0, quoted = false, escaped = false;
  for (final c in text.codeUnits) {
    if (quoted) {
      if (escaped) {
        escaped = false;
      } else if (c == 92) {
        escaped = true;
      } else if (c == 34) {
        quoted = false;
      }
    } else if (c == 34) {
      quoted = true;
    } else if (c == 123 || c == 91) {
      if (++depth > 40) throw StateError('JSON 嵌套过深');
    } else if (c == 125 || c == 93) {
      if (--depth < 0) throw StateError('JSON 结构错误');
    }
  }
  final v = decodeQuantJson(text);
  if (v is! Map<String, dynamic>) throw StateError('需要 JSON 对象');
  quantCanonical(v); // Reject floats and non-interoperable integer literals.
  return v;
}

String fqeHash(List<int> bytes) => quantSha256(bytes);
String fqeInputId(Map<String, dynamic> v) =>
    fqeHash(utf8.encode(quantCanonical(v)));
String fqeResultId(List<int> bytes) =>
    'sha256:${fqeHash([...utf8.encode('FQE-BACKTEST-RESULT/1\n'), ...bytes])}';

/// One app owns the store. Immutable records use a synced temporary file and
/// atomic rename. Failed/partial/corrupt originals are preserved, never repaired.
class FqeStore {
  FqeStore(this.directory);
  final Directory directory;
  RandomAccessFile? _lease;
  Future<void> _tail = Future<void>.value();
  bool _closing = false;
  Future<void> initialize() async {
    await directory.create(recursive: true);
    if (await FileSystemEntity.isLink(directory.path)) {
      throw StateError('数据目录不能是链接');
    }
    final lease =
        await File('${directory.path}/owner.lock').open(mode: FileMode.append);
    try {
      await lease.lock(FileLock.exclusive);
    } catch (_) {
      await lease.close();
      rethrow;
    }
    _lease = lease;
  }

  Future<T> _serial<T>(Future<T> Function() work) {
    if (_closing || _lease == null) {
      return Future<T>.error(StateError('本地存储未就绪'));
    }
    final result = _tail.then((_) => work());
    _tail = result.then<void>((_) {}, onError: (Object _, StackTrace __) {});
    return result;
  }

  Future<void> put(String kind, String id, Map<String, dynamic> payload) =>
      _serial(() {
        final root = directory.path;
        final text = quantCanonical(payload);
        return _backgroundWrite(root, kind, id, text);
      });
  Future<List<Map<String, dynamic>>> list(String kind) => _serial(() {
        final root = directory.path;
        return _backgroundList(root, kind);
      });
  Future<Map<String, dynamic>> read(String kind, String id) => _serial(() {
        final root = directory.path;
        return _backgroundRead(root, kind, id);
      });
  Future<void> close() async {
    _closing = true;
    await _tail;
    await _lease?.unlock();
    await _lease?.close();
    _lease = null;
  }
}

Future<void> _backgroundWrite(
        String root, String kind, String id, String text) =>
    Isolate.run(() => _write(root, kind, id, text));
Future<List<Map<String, dynamic>>> _backgroundList(String root, String kind) =>
    Isolate.run(() => _list(root, kind));
Future<Map<String, dynamic>> _backgroundRead(
        String root, String kind, String id) =>
    Isolate.run(() => _read(root, kind, id));
void _key(String kind, String id) {
  if (!['draft', 'run', 'project'].contains(kind) ||
      !RegExp(r'^[a-zA-Z0-9._-]{1,80}$').hasMatch(id)) {
    throw StateError('记录标识无效');
  }
}

File _file(String root, String kind, String id) {
  _key(kind, id);
  return File('$root/$kind-$id.json');
}

Map<String, dynamic> _read(String root, String kind, String id) {
  final file = _file(root, kind, id);
  if (FileSystemEntity.typeSync(file.path, followLinks: false) !=
          FileSystemEntityType.file ||
      file.lengthSync() > fqeRecordLimit * 2) throw StateError('记录缺失、链接或超出限制');
  final value = fqeJson(file.readAsStringSync(), max: fqeRecordLimit * 2);
  final text = value['payload'];
  if (value.length != 6 ||
      value['format'] != 'finger-desk.fqe-record/1' ||
      value['backend'] != 'fqe-native/1' ||
      value['kind'] != kind ||
      value['id'] != id ||
      text is! String ||
      value['sha256'] != fqeHash(utf8.encode(text))) {
    throw StateError('记录版本、来源或校验失败；原文件已保留');
  }
  return fqeJson(text);
}

List<Map<String, dynamic>> _list(String root, String kind) {
  _key(kind, 'scan');
  final result = <Map<String, dynamic>>[];
  var count = 0;
  for (final entity in Directory(root).listSync(followLinks: false)) {
    if (++count > 400) throw StateError('本地记录目录超出限制');
    final name = entity.uri.pathSegments.last;
    if (!name.startsWith('$kind-') || !name.endsWith('.json')) continue;
    final id = name.substring(kind.length + 1, name.length - 5);
    try {
      final v = _read(root, kind, id);
      result.add({
        'id': id,
        'name': v['name'],
        'phase': v['phase'],
        'created': v['created'],
        if (kind == 'project') ...{
          'project_id': v['id'],
          'revision': v['revision'],
          'generation': v['generation']
        }
      });
    } catch (e) {
      result.add({'id': id, 'error': '$e'});
    }
  }
  result.sort((a, b) => '${b['created']}'.compareTo('${a['created']}'));
  return result;
}

void _write(String root, String kind, String id, String text) {
  final target = _file(root, kind, id);
  if (utf8.encode(text).length > fqeRecordLimit) throw StateError('记录超出大小限制');
  final wrapper = quantCanonical({
    'format': 'finger-desk.fqe-record/1',
    'backend': 'fqe-native/1',
    'kind': kind,
    'id': id,
    'payload': text,
    'sha256': fqeHash(utf8.encode(text))
  });
  if (target.existsSync()) {
    if (quantCanonical(_read(root, kind, id)) != text) {
      throw StateError('不可覆盖已有记录');
    }
    return;
  }
  var total = 0, same = 0, count = 0;
  for (final entity in Directory(root).listSync(followLinks: false)) {
    if (++count > 400) throw StateError('本地记录目录超出限制');
    if (FileSystemEntity.typeSync(entity.path, followLinks: false) !=
        FileSystemEntityType.file) {
      throw StateError('数据目录包含非普通文件');
    }
    total += File(entity.path).lengthSync();
    final name = entity.uri.pathSegments.last;
    if (name.startsWith('$kind-') && name.endsWith('.json')) same++;
  }
  if (same >= (kind == 'run' ? 256 : 64) ||
      total + utf8.encode(wrapper).length > fqeStoreLimit) {
    throw StateError('本地记录已达上限，请先备份管理；不会自动删除历史');
  }
  final pending = File('${target.path}.pending');
  if (pending.existsSync()) throw StateError('发现未完成写入，原文件已保留');
  pending.createSync(exclusive: true);
  final out = pending.openSync(mode: FileMode.writeOnly);
  try {
    out.writeStringSync(wrapper);
    out.flushSync();
  } finally {
    out.closeSync();
  }
  pending.renameSync(target.path);
}

