void check(bool value, String label) {
  if (!value) throw StateError(label);
}

Future<void> rejects(FutureOr<void> Function() run, String label) async {
  try {
    await run();
  } catch (_) {
    return;
  }
  throw StateError('expected rejection: $label');
}

Future<void> idle(FqeApplicationService service) async {
  final timer = Stopwatch()..start();
  while (service.busy) {
    if (timer.elapsedMilliseconds > 10000) {
      throw TimeoutException('native project run');
    }
    await Future<void>.delayed(const Duration(milliseconds: 5));
  }
  check(service.failure == null, '${service.failure}');
}

