    check(
        replay.seek('6', 'open').account['cash'] == '96.00' &&
            replay.seek('6', 'open').account['quantity'] == '1.000' &&
            replay.seek('6', 'open').equity == null,
        'open fill native account without invented equity');
    check(
        replay.seek('6', 'close').equity!['equity'] == '98.00' &&
            replay.seek('7', 'close').equity!['equity'] == '97.00',
        'native close equity');
    check(
        replay.seek('8', 'open').account['cash'] == '98.00' &&
            replay.seek('8', 'open').account['quantity'] == '0.000',
        'next-open sale');
    final borrowedFrame = replay.seek('6', 'open').account;
    borrowedFrame['cash'] = '0.00';
    check(
        replay.seek('6', 'open').account['cash'] == '96.00', 'immutable frame');
    await rejects(
        () => FqeNativeReplay.fromRecord({...service.current!, 'report': '{}'}),
        'damaged replay');
    await rejects(() => replay.seek('99', 'close'), 'unknown source cursor');
    checks.add('read-only-native-replay-phases-and-damaged-result-rejection');

    // Hold a native result after it is computed; edit the buffer before delivery.
    Completer<void>? release, arrived;
    Future<Map<String, dynamic>> delayed(
        String method, Map<String, dynamic> params) async {
      final result = await service.authoringRpc(method, params);
      if (release != null && method == 'authoring.inspect') {
        arrived!.complete();
        await release.future;
      }
      return result;
    }

    final race = await FqeAuthoringProject.create(
        name: 'race', source: source, rpc: delayed);
    race.editText('// first\n$source');
    release = Completer<void>();
    arrived = Completer<void>();
    final applying = race.apply(race.revision, race.generation);
    final rejected = rejects(() => applying, 'late native response');
    await arrived.future;
    race.editText('fqe 1; newer invalid buffer');
    release.complete();
    await rejected;
    check(race.buffer == 'fqe 1; newer invalid buffer' && !race.executable,
        'late result cannot publish');
    checks.add('late-native-response-cannot-overwrite-new-text');
    // Change configuration after preflight has returned but before admission.
    final stale = restored.freeze();
    var guardCalls = 0;
    await rejects(
        () => service.startAssociated(stale.input, project: stale.association,
                requireCurrent: () {
              if (++guardCalls == 2) {
                restored.setResearch({...restored.research, 'seed': '0'});
              }
              restored.requireCurrent(stale);
            }),
        'edit after preflight');
    check(guardCalls == 2, 'actual asynchronous preflight boundary');
    checks.add('post-preflight-change-rejected-before-native-start');
    final output = {
      'format': 'finger-desk.fqe-authoring-project-evidence/1',
      'status': 'passed',
      'peer_sha256': bundle['executable_sha256'],
      'bridge_id': hello['bridge_id'],
      'project_ids': [p.id, q.id],
      'checks': checks,
      'baseline_equity': '98.00',
      'variant_equity': '100.00',
      'baseline_result_id': aResult,
      'store': directory.path
    };
    await File(args[1]).writeAsString(
        '${const JsonEncoder.withIndent('  ').convert(output)}\n');
    stdout.writeln(jsonEncode(output));
  } finally {
    await service.shutdown();
    await directory.delete(recursive: true);
  }
}
